import { TableAdapter } from '@dreadnought/react/unstyled';
type Person = { key: number; name: string; age: number };
const example = <TableAdapter<Person> pagination={false} slotProps={{ tooltip: { openDelay: 0 } }} dataSource={[{ key: 1, name: 'Long full name', age: 29 }]} columns={[{ key: 'name', title: 'Name', dataIndex: 'name', width: 120, ellipsis: true }, { key: 'age', title: 'Age', dataIndex: 'age', align: 'right', hidden: false }]} />;

import { TableAdapter } from '@dreadnought/react/unstyled';
type Person = { key: number; name: string; city: string };
const example = <TableAdapter<Person> sticky pagination={false} dataSource={[{ key: 1, name: 'Anna', city: 'Moscow' }]} columns={[{ key: 'person', title: 'Person', children: [{ key: 'name', title: 'Name', dataIndex: 'name' }, { key: 'city', title: 'City', dataIndex: 'city' }] }]} />;

import { TableAdapter } from '@dreadnought/react/unstyled';
type Person = { key: number; name: string };
const example = <TableAdapter<Person> pagination={false} dataSource={[{ key: 1, name: 'Anna' }]} columns={[{ key: 'name', title: 'Name', dataIndex: 'name' }]} expandable={{ expandedRowRender: record => <p>{record.name}</p>, defaultExpandedRowKeys: [1] }} />;

import { TableAdapter } from '@dreadnought/react/unstyled';
type Member = { key: number; team: string };
const example = <TableAdapter<Member> pagination={false} dataSource={[{ key: 1, team: 'Design' }, { key: 2, team: 'Design' }]} onRow={record => ({ title: String(record.key) })} columns={[{ key: 'team', title: 'Team', dataIndex: 'team', onCell: (_record, index) => ({ rowSpan: index === 0 ? 2 : 0 }), onHeaderCell: () => ({ title: 'Team name' }) }]} />;

import { TableAdapter } from '@dreadnought/react/unstyled';
export function Example() {
  return <TableAdapter rowKey="id" dataSource={[{ id: 1, name: 'Борис' }, { id: 2, name: 'Анна' }]} columns={[{ key: 'name', title: 'Имя', dataIndex: 'name', sorter: (a, b) => a.name.localeCompare(b.name) }]} />;
}
